import{_ as r,l,o as e,c,v as t,p as s,x as i,d as o,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"内联缓存","description":"","frontmatter":{"title":"内联缓存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/inline-caching.md","filePath":"cs/inline-caching.md","lastUpdated":1789023840000}'),p={name:"cs/inline-caching.md"};function m(C,a,I,_,u,f){const n=l("Mermaid");return e(),c("div",null,[a[1]||(a[1]=t('<h1 id="内联缓存" tabindex="-1">内联缓存 <a class="header-anchor" href="#内联缓存" aria-label="Permalink to &quot;内联缓存&quot;">​</a></h1><div class="epigraph"><p>调用点记住上次接收者的类与方法地址：同类则直跳，不同类则回慢速查找。单态缓存命中时，动态分派接近静态调用。</p><footer>—— 据 Deutsch and Schiffman；Hölzle, Chambers and Ungar, Optimizing Dynamically-Typed Object-Oriented Languages with PICs 整理</footer></div><p>上一课<a href="/cs/tracing-jit">追踪 JIT</a> 沿路径投机类型。缺口是<strong>调用点投机</strong>：内联缓存（IC）。Smalltalk/Self/JS：方法查找贵。单态 IC：一个类；PIC：几个类的跳表。本课钉 IC，去优化下一课收失败。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>vtable 对静态类层次快；动态语言形状（hidden class）运行时变。IC：调用点状态机。缺口是<strong>把查找结果焊在调用点</strong>，不是整段 trace。</p><p>与<a href="/cs/typeclass-dictionary">类型类字典</a>：都是间接调用，IC 可改成直跳并内联。</p><h3 id="ic-不是-cpu-的-i-cache" tabindex="-1">IC 不是 CPU 的 I-cache <a class="header-anchor" href="#ic-不是-cpu-的-i-cache" aria-label="Permalink to &quot;IC 不是 CPU 的 I-cache&quot;">​</a></h3><p>Inline cache 是语言实现；instruction cache 是硬件。不要混名。</p><p><span class="marginnote">Deutsch–Schiffman。Hölzle–Chambers–Ungar PIC（OOPSLA）。V8/IC 状态机是工程后裔。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>未初始化：查表，填缓存。单态：比较类字，命中则调用缓存地址。失配：变多态或 MEGAMORPHIC（回哈希）。JIT 可对单态直接内联，失配去优化。</p>',11)),(e(),s(d,null,{default:i(()=>[h(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22%E8%B0%83%E7%94%A8%E7%82%B9%22%5D%20--%3E%20MONO%5B%22%E5%8D%95%E6%80%81%20IC%22%5D%0A%20%20MONO%20--%3E%20PIC%5B%22%E5%A4%9A%E6%80%81%20IC%22%5D%0A%20%20PIC%20--%3E%20MEGA%5B%22%E5%93%88%E5%B8%8C%E6%9F%A5%E6%89%BE%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与逃逸/形状：对象布局稳定 IC 才稳。隐藏类转移会刷缓存。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>线程：IC 更新要原子或每线程。不要无限 PIC 变大。统计：调用点的多态度决定是否内联。</p><p>与方法 JIT：编译时把 IC 变成 cmp+je 序列。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写去优化栈重写。后课默认：动态调用用 IC。下一课去优化：投机失败如何回解释器状态。</p><p>也不把 IC 当 HTTP 缓存。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IC：调用点缓存接收者类与目标。</li><li>单态可内联；超多态回慢路径。</li><li>与 vtable 静态分派 complementary。</li><li>出处：Deutsch and Schiffman；Hölzle, Chambers and Ungar。</li></ul>',9))])}const T=r(p,[["render",m]]);export{b as __pageData,T as default};
